    private void formWindowGainedFocus(java.awt.event.WindowEvent evt) {//GEN-FIRST:event_formWindowGainedFocus
         DefaultTableModel model = (DefaultTableModel) jTable1.getModel();
        try{
           try {
               //REGISTER
               Class.forName("com.mysql.cj.jdbc.Driver");
               //Class.forName("java.sql.driver");
           } catch ( Exception ex) {
               System.out.println(ex);
           }

            //CONNECTION
       String db_url="jdbc:mysql://localhost:3306/travel";
       String pwd="arjun";
       String user="root";

       Connection conn=DriverManager.getConnection(db_url,user,pwd);

       //EXECUTED QUERIES
        stmt=(Statement) conn.createStatement();

          rs=stmt.executeQuery(sql);



    while (rs.next()) {
                String no = rs.getString("TYPE_NO");
                String name = rs.getString("TYPE_NAME");
                String disc = rs.getString("TYPE_DISC");

              System.out.println(no + "|" + name + "|" + disc );
                model.addRow(new Object[] {no,name,disc});
            }


}
catch(SQLException e){
 JOptionPane.showMessageDialog(this, e.getMessage()+"  "+'\n' + " YOU HAVE AN ERROR IN CONNECTION PLEASE CORRECT IT");
                   }
    }//GEN-LAST:event_formWindowGainedFocus

